import{_ as o,o as e,c as a,a2 as r}from"./chunks/framework.CdvW4CUT.js";const c=JSON.parse('{"title":"开博第一篇:为什么写博客","description":"","frontmatter":{},"headers":[],"relativePath":"posts/hello-world.md","filePath":"posts/hello-world.md","lastUpdated":1792903128000}'),l={name:"posts/hello-world.md"};function s(i,t,n,u,d,p){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="开博第一篇-为什么写博客" tabindex="-1">开博第一篇:为什么写博客 <a class="header-anchor" href="#开博第一篇-为什么写博客" aria-label="Permalink to &quot;开博第一篇:为什么写博客&quot;">​</a></h1><blockquote><p>2026-10-25</p></blockquote><p>博客开张了。第一篇文章不讲技术,讲清楚两件事:我为什么要写,以及打算怎么写。</p><h2 id="为什么写" tabindex="-1">为什么写 <a class="header-anchor" href="#为什么写" aria-label="Permalink to &quot;为什么写&quot;">​</a></h2><p>对内的原因有三个,按重要性排:</p><ol><li><strong>倒逼理解</strong>。一个东西&quot;能讲清楚&quot;和&quot;能用&quot;是两回事。写作是最好的检验手段,所有&quot;以为懂了其实没懂&quot;的地方,写的时候都会暴露出来。</li><li><strong>个人知识库</strong>。半年前怎么解决的那个诡异问题,我一定会忘。自己的文章是回查成本最低的方式。</li><li><strong>梳理体系</strong>。零散的知识点只有写出来才会串成结构。</li></ol><p>对外的原因很简单:一篇有深度的排查文章,是普通程序员成本最低的&quot;作品集&quot;。它还能把面试引导到我熟悉的领域——文章写在哪里,面试就聊哪里。</p><h2 id="打算怎么写" tabindex="-1">打算怎么写 <a class="header-anchor" href="#打算怎么写" aria-label="Permalink to &quot;打算怎么写&quot;">​</a></h2><p>给自己立几条规矩:</p><ul><li><strong>写过程,不写结论</strong>。&quot;最后用了方案 B&quot;没有价值,&quot;为什么排除了方案 A、中间错过了什么线索、怎么定位到根因的&quot;才有价值。弯路也是文章的一部分。</li><li><strong>趁热写</strong>。问题解决完当天或周末就写,拖过两周细节就忘光了。</li><li><strong>先发布,再迭代</strong>。不憋完美文章,写完就发,回头有新理解再改。</li><li><strong>月更,但不水文</strong>。一个月一篇有含量的,好过一周一篇流水账。</li></ul><h2 id="这个博客本身" tabindex="-1">这个博客本身 <a class="header-anchor" href="#这个博客本身" aria-label="Permalink to &quot;这个博客本身&quot;">​</a></h2><p>这个站是用 VitePress 搭的,托管在 GitHub Pages 上,源码在 <a href="https://github.com/66ou66/66ou66.github.io" target="_blank" rel="noreferrer">GitHub</a>。写作流程:本地 <code>npm run dev</code> 实时预览,写完 <code>npm run deploy</code> 发布。</p><p>搭建的完整过程——包括一次被 GitHub 拒绝的推送——写在下一篇文章:<a href="./build-this-blog.html">我是怎么搭建这个博客的</a>。</p><p>以后每解决一个值得记的问题,这里就会多一篇。</p>',14)])])}const q=o(l,[["render",s]]);export{c as __pageData,q as default};
